    float *angG = aw_s->angG;
    uint32_t fpdL = aw_s->fpdL;
    uint32_t fpdR = aw_s->fpdR;
    uint32_t aw_rand = aw_s->aw_rand;
    {
	A = 0.7;
	B = 0.1;
	C = 0.8;
	D = 0.6;
	E = 0.4;
	F = 0.1;
	G = 0.8;
	H = 0.5;
	I = 0.0;
	J = 0.3;
	
	for(int x=0; x<17; x++) {
		for(int y=0; y<11; y++) {
			angSL[x][y] = 0.0;angAL[x][y] = 0.0;
			angSR[x][y] = 0.0;angAR[x][y] = 0.0;
		}
	}
	for(int y=0; y<11; y++) {
		angG[y] = 0.0;
		for (int x = 0; x < bip_total; x++) bip[x][y] = 0.0;
	}
	for(int count = 0; count < 36; count++) {
		iirHPositionL[count] = 0.0;
		iirHAngleL[count] = 0.0;
		iirBPositionL[count] = 0.0;
		iirBAngleL[count] = 0.0;
		iirHPositionR[count] = 0.0;
		iirHAngleR[count] = 0.0;
		iirBPositionR[count] = 0.0;
		iirBAngleR[count] = 0.0;
	}
	WasNegativeL = false;
	ZeroCrossL = 0;
	gaterollerL = 0.0;	
	WasNegativeR = false;
	ZeroCrossR = 0;
	gaterollerR = 0.0;	
	
	fpdL = 1.0; fpdL = aw_seed(0);
	fpdR = 1.0; fpdR = aw_seed(1); // default program name
	aw_rand = AW_RAND_SEED;
}
    aw_s->A = A;
    aw_s->B = B;
    aw_s->C = C;
